input.newString:
// asteroids - draw as shaded circles
asteroids.forEach(a => {
  const grad = ctx.createRadialGradient(
    a.x + a.w / 2,
    a.y + a.h / 2,
    a.w * 0.1,
    a.x + a.w / 2,
    a.y + a.h / 2,
    a.w / 2
  );
  grad.addColorStop(0, '#b5651d');
  grad.addColorStop(1, '#4b2e1e');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(a.x + a.w / 2, a.y + a.h / 2, a.w / 2, 0, Math.PI * 2);
  ctx.fill();
});

